create or replace function public.get_seller_studio_metrics(p_store_id uuid, p_start timestamptz default now() - interval '30 days', p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path = public as $$
declare result jsonb; v_owner_id uuid;
begin
 select s.owner_id into v_owner_id from public.stores s where s.id=p_store_id;
 if v_owner_id is null or v_owner_id <> auth.uid() then raise exception 'Not allowed'; end if;
 select jsonb_build_object('products',(select count(*) from public.products p where p.store_id=p_store_id),'services',(select count(*) from public.services srv where srv.owner_id=v_owner_id),'orders',(select count(*) from public.orders o where o.store_id=p_store_id and o.created_at between p_start and p_end),'paid_orders',(select count(*) from public.orders o where o.store_id=p_store_id and o.created_at between p_start and p_end and lower(coalesce(o.payment_status,'')) in ('paid','success','successful','completed')),'gross_revenue',coalesce((select sum(o.subtotal) from public.orders o where o.store_id=p_store_id and o.created_at between p_start and p_end and lower(coalesce(o.payment_status,'')) in ('paid','success','successful','completed')),0),'pending_revenue',coalesce((select sum(o.subtotal) from public.orders o where o.store_id=p_store_id and o.created_at between p_start and p_end and lower(coalesce(o.payment_status,'')) not in ('paid','success','successful','completed')),0),'visitors',(select count(distinct coalesce(nullif(e.session_id,''),e.actor_id::text,e.id::text)) from public.seller_events e where e.store_id=p_store_id and e.actor_id is distinct from v_owner_id and e.created_at between p_start and p_end),'views',(select count(*) from public.seller_events e where e.store_id=p_store_id and e.actor_id is distinct from v_owner_id and e.event_type in ('impression','view') and e.created_at between p_start and p_end),'engagement',(select count(*) from public.seller_events e where e.store_id=p_store_id and e.actor_id is distinct from v_owner_id and e.event_type='engagement' and e.created_at between p_start and p_end),'clicks',(select count(*) from public.seller_events e where e.store_id=p_store_id and e.actor_id is distinct from v_owner_id and e.event_type='product_click' and e.created_at between p_start and p_end),'carts',(select count(*) from public.seller_events e where e.store_id=p_store_id and e.actor_id is distinct from v_owner_id and e.event_type='cart' and e.created_at between p_start and p_end),'checkouts',(select count(*) from public.seller_events e where e.store_id=p_store_id and e.actor_id is distinct from v_owner_id and e.event_type='checkout' and e.created_at between p_start and p_end),'purchases',(select count(*) from public.orders o where o.store_id=p_store_id and o.created_at between p_start and p_end and lower(coalesce(o.payment_status,'')) in ('paid','success','successful','completed')),'customers',(select count(distinct o.buyer_id) from public.orders o where o.store_id=p_store_id and o.created_at between p_start and p_end and lower(coalesce(o.payment_status,'')) in ('paid','success','successful','completed')),'favourites',(select count(*) from public.product_likes l join public.products p on p.id=l.product_id where p.store_id=p_store_id and l.created_at between p_start and p_end),'withdrawn',coalesce((select sum(p.amount) from public.seller_payouts p where p.store_id=p_store_id and lower(p.status) in ('paid','completed')),0),'transactions',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'amount',q.subtotal,'status',q.payment_status,'fulfillment_status',q.fulfillment_status,'created_at',q.created_at) order by q.created_at desc) from (select o.id,o.subtotal,o.payment_status,o.fulfillment_status,o.created_at from public.orders o where o.store_id=p_store_id order by o.created_at desc limit 25) q),'[]'::jsonb)) into result;
 return result;
end; $$;
grant execute on function public.get_seller_studio_metrics(uuid,timestamptz,timestamptz) to authenticated;
drop function if exists public.get_seller_studio_visitors(uuid,timestamptz,timestamptz);
create or replace function public.get_seller_studio_visitors(p_store_id uuid, p_start timestamptz default now() - interval '30 days', p_end timestamptz default now()) returns table(user_id uuid, display_name text, handle text, avatar_url text, last_seen timestamptz, visits bigint) language plpgsql security definer set search_path = public as $$
declare v_owner_id uuid;
begin
 select s.owner_id into v_owner_id from public.stores s where s.id=p_store_id;
 if v_owner_id is null or v_owner_id <> auth.uid() then raise exception 'Not allowed'; end if;
 return query select e.actor_id, coalesce(pr.display_name,pr.handle,'Visitor'), pr.handle, pr.avatar_url, max(e.created_at), count(*) from public.seller_events e join public.profiles pr on pr.id=e.actor_id where e.store_id=p_store_id and e.actor_id is not null and e.actor_id <> v_owner_id and e.event_type in ('impression','view','engagement','product_click') and e.created_at between p_start and p_end group by e.actor_id,pr.display_name,pr.handle,pr.avatar_url order by max(e.created_at) desc;
end; $$;
grant execute on function public.get_seller_studio_visitors(uuid,timestamptz,timestamptz) to authenticated;